/** Independent source/fixed-fact oracle, no production table/helper import. */
import assert from'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import facts from'./legacy-2018-pm-cloud-facts.json';
export function legacy2018CloudAvailability(bits:readonly boolean[]){assert.equal(bits.length,9);const ok=(...ns:number[])=>ns.every(i=>bits[i]);return{uploadStoreAndEnqueue:ok(0,1,3,4,5,7),classification:ok(6,5,4,7),completeUploadProcessing:ok(0,1,3,4,5,7,6),searchExistingReplicatedPhoto:ok(0,1,3,4,2,8),fetchWithAlreadyKnownURL:ok(0,2,8),replication:ok(8,7)};}
export function legacy2018CloudOracle(body:GeneratedBody,values:readonly number[]){
 assert.equal(values.length,2);assert(values.every(n=>Number.isSafeInteger(n)&&n>=0&&n<=3));const v=values[0],w=values[1],network=Number(facts.networkSeconds[v]),photos=facts.hourlyPhotos[w],expected=facts.sourceBlocks;
 assert.equal(body.prompt.length,expected.length);for(const[i,e]of expected.entries()){const b=body.prompt[i];if(e.kind==='p'){assert(b.type==='paragraph');assert.equal(b.text,e.text!.replace('ネットワーク処理量は0.07秒','ネットワーク処理量は'+facts.networkSeconds[v]+'秒').replace('4,000枚',photos.toLocaleString('en-US')+'枚'));}else if(e.kind==='table'){assert(b.type==='table');const t=facts.tables[String(e.table)as keyof typeof facts.tables];assert.deepEqual(b,{type:'table',caption:'表'+e.table+' '+t.caption,columns:t.headers,rows:t.rows});}else{assert(b.type==='diagram'&&b.scene.kind==='source_figure');assert.equal(b.scene.profile,'legacy-2018-cloud-topology');assert.deepEqual(b.scene.values,[0]);assert.equal(b.caption,'図1 システム構成');assert.equal(b.alt,facts.figureAlt);}}
 const table=body.prompt.find(b=>b.type==='table');assert(table?.type==='table');const rows=table.rows;const net100=BigInt(Math.round(network*100));
 // Fixed-point rationals: 0.1=10/100. Compare price*max(10/cpu,net100/net) using cross products, without production rate code.
 const ratios=rows.map(r=>{const cpu=BigInt(r[1]),net10=BigInt(Math.round(Number(r[2])*10)),price=BigInt(r[3]);const cpuN=10n,cpuD=cpu,netN=net100*10n,netD=net10;return cpuN*netD>=netN*cpuD?[price*cpuN,cpuD]as const:[price*netN,netD]as const;});
 const compare=(a:readonly bigint[],b:readonly bigint[])=>a[0]*b[1]-b[0]*a[1];const best=ratios.map((r,i)=>ratios.every(s=>compare(r,s)<=0)?i:-1).filter(i=>i>=0);assert.equal(best.length,1);assert.equal(rows[best[0]][0],facts.aCorrectType[v]);
 const discrete=rows.map(r=>{for(let n=1;n<100000;n++)if(n*Number(r[1])*.5>=1000*.1&&n*Number(r[2])*.5>=1000*network)return n*Number(r[3]);throw Error('NO_INTEGER_VM');});assert.equal(discrete.indexOf(Math.min(...discrete)),best[0]);
 let needed=0;while(needed*8*3600/2<photos*25)needed++;assert.equal(needed,facts.bCorrect[w]);assert((needed-1)*8*3600/2<photos*25);assert(needed*8*3600/2>=photos*25);
 const choices=[...facts.originalChoices[0],...facts.bChoices[w].map(String),...facts.originalChoices[2],...facts.originalChoices[3]];assert.deepEqual(body.choices,choices.map(text=>[{type:'paragraph',text}]));
 const incoming:Record<number,[number|string,number][]>={1:[['Internet',443]],2:[[1,80]],3:[[2,15432],[2,15672],[4,15432],[4,15672]],4:[],5:[[2,80],[4,80],[6,80]],6:[[1,80]]};const csets=[[1,2,5,6],[2,5,6],[2,6],[5,6]],ct=csets.map(g=>new Set(g.map(i=>JSON.stringify(incoming[i]))).size===1);assert.deepEqual(ct,facts.cTruth);
 const healthy=Array<boolean>(9).fill(true),storageDown=[...healthy],frontDown=[...healthy];storageDown[7]=false;frontDown[3]=false;const s=legacy2018CloudAvailability(storageDown),f=legacy2018CloudAvailability(frontDown);assert(s.searchExistingReplicatedPhoto&&!s.completeUploadProcessing);assert(f.fetchWithAlreadyKnownURL&&!f.searchExistingReplicatedPhoto);const adv=[true,1<0,s.searchExistingReplicatedPhoto,s.completeUploadProcessing,f.searchExistingReplicatedPhoto];assert.deepEqual(adv,facts.advantageTruth);
 assert.equal(body.contexts,undefined);assert.equal(body.correctIndex,undefined);assert.deepEqual(body.answerParts,facts.partIds.map((id,i)=>({id,label:facts.partLabels[i],choiceIds:Array.from({length:i<3?4:5},(_,j)=>'choice-value-'+([0,4,8,12,12][i]+j+1))})));
 assert.deepEqual(body.partAnswers,[{kind:'choice',partId:'part-a',choiceId:'choice-value-'+(best[0]+1)},{kind:'choice',partId:'part-b',choiceId:'choice-value-6'},{kind:'choice',partId:'part-c',choiceId:'choice-value-11'},{kind:'unordered',partIds:['part-choice1','part-choice2'],choiceIds:['choice-value-13','choice-value-15']}]);
 const shown=ratios.map(r=>Number((Number(r[0])/Number(r[1])/50).toFixed(4)));assert(body.explanation.includes('A〜Dの比較係数は'+shown.join('、')+'となり、'+facts.aCorrectType[v]+'が最小'));
 for(const re of[/それぞれ50%|50%まで/,/両|通信能力/,new RegExp(photos+'×25='+photos*25),new RegExp(needed+'台'),/14400/,/許可元グループ/,/15432.*15672/,/既に分類・複製/,/最新投稿全件の即時同期/,/既知URL/,/一意ID/])assert.match(body.explanation,re);
 return{truth:[...rows.map((_,i)=>i===best[0]),...facts.bChoices[w].map(n=>n===needed),...ct,...adv],aIndex:best[0],b:needed,photos,network};
}
